#!/usr/bin/env python3
"""A small persistent HTTP key-value service using only the standard library."""

from __future__ import annotations

import argparse
import json
import math
import os
import signal
import sys
import tempfile
import threading
import time
from http import HTTPStatus
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from typing import Any
from urllib.parse import unquote_to_bytes, urlsplit


MAX_BODY = 1024 * 1024


class StoreError(Exception):
    pass


class PersistentStore:
    def __init__(self, path: Path):
        self.path = path
        self.lock = threading.RLock()
        self.entries: dict[str, dict[str, Any]] = {}
        self._load()

    def _load(self) -> None:
        try:
            if self.path.exists():
                with self.path.open("r", encoding="utf-8") as stream:
                    raw = json.load(stream)
                if not isinstance(raw, dict) or raw.get("version") != 1 or not isinstance(raw.get("entries"), dict):
                    raise StoreError("invalid data-file format")
                now = time.time()
                for key, entry in raw["entries"].items():
                    if not isinstance(key, str) or not isinstance(entry, dict) or "value" not in entry:
                        raise StoreError("invalid entry in data file")
                    expires = entry.get("expires_at")
                    if expires is not None and (not isinstance(expires, (int, float)) or isinstance(expires, bool) or not math.isfinite(expires)):
                        raise StoreError("invalid expiry in data file")
                    if expires is None or expires > now:
                        self.entries[key] = {"value": entry["value"], "expires_at": expires}
                if len(self.entries) != len(raw["entries"]):
                    self._persist(self.entries)
        except StoreError:
            raise
        except (OSError, ValueError, TypeError, json.JSONDecodeError) as exc:
            raise StoreError(f"cannot load data file: {exc}") from exc

    def _persist(self, entries: dict[str, dict[str, Any]]) -> None:
        parent = self.path.parent
        temp_name: str | None = None
        try:
            parent.mkdir(parents=True, exist_ok=True)
            payload = {"version": 1, "entries": entries}
            with tempfile.NamedTemporaryFile(
                mode="w", encoding="utf-8", dir=parent, prefix=f".{self.path.name}.", delete=False
            ) as stream:
                temp_name = stream.name
                json.dump(payload, stream, ensure_ascii=False, separators=(",", ":"), allow_nan=False)
                stream.write("\n")
                stream.flush()
                os.fsync(stream.fileno())
            os.replace(temp_name, self.path)
            temp_name = None
            try:
                directory_fd = os.open(parent, os.O_RDONLY)
                try:
                    os.fsync(directory_fd)
                finally:
                    os.close(directory_fd)
            except OSError:
                pass
        except (OSError, ValueError, TypeError) as exc:
            raise StoreError(f"cannot persist data: {exc}") from exc
        finally:
            if temp_name is not None:
                try:
                    os.unlink(temp_name)
                except OSError:
                    pass

    @staticmethod
    def _live(entries: dict[str, dict[str, Any]], now: float) -> dict[str, dict[str, Any]]:
        return {
            key: entry
            for key, entry in entries.items()
            if entry["expires_at"] is None or entry["expires_at"] > now
        }

    def _prune(self) -> None:
        live = self._live(self.entries, time.time())
        if len(live) != len(self.entries):
            self._persist(live)
            self.entries = live

    def put(self, key: str, value: Any, ttl: float | None) -> bool:
        with self.lock:
            self._prune()
            created = key not in self.entries
            updated = dict(self.entries)
            updated[key] = {
                "value": value,
                "expires_at": None if ttl is None else time.time() + ttl,
            }
            self._persist(updated)
            self.entries = updated
            return created

    def get(self, key: str) -> tuple[bool, Any]:
        with self.lock:
            self._prune()
            entry = self.entries.get(key)
            return (False, None) if entry is None else (True, entry["value"])

    def delete(self, key: str) -> bool:
        with self.lock:
            self._prune()
            if key not in self.entries:
                return False
            updated = dict(self.entries)
            del updated[key]
            self._persist(updated)
            self.entries = updated
            return True

    def keys(self) -> list[str]:
        with self.lock:
            self._prune()
            return sorted(self.entries)


class Server(ThreadingHTTPServer):
    daemon_threads = True
    allow_reuse_address = True

    def __init__(self, address: tuple[str, int], store: PersistentStore):
        self.store = store
        super().__init__(address, Handler)


class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"
    server: Server

    def _send(self, status: int, payload: Any | None = None, *, headers: dict[str, str] | None = None) -> None:
        body = b"" if payload is None else json.dumps(payload, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        if headers:
            for name, value in headers.items():
                self.send_header(name, value)
        self.end_headers()
        if body and self.command != "HEAD":
            self.wfile.write(body)

    def _error(self, status: int, message: str) -> None:
        self._send(status, {"error": message})

    def _key(self) -> tuple[str | None, str | None]:
        path = urlsplit(self.path).path
        prefix = "/v1/kv/"
        if not path.startswith(prefix):
            return None, "unknown route"
        encoded = path[len(prefix):]
        if not encoded:
            return None, "key must not be empty"
        try:
            key = unquote_to_bytes(encoded).decode("utf-8", errors="strict")
        except UnicodeDecodeError:
            return None, "key must be valid UTF-8"
        if not key or "/" in key:
            return None, "key must not be empty or contain '/'"
        return key, None

    def _read_json(self) -> tuple[Any | None, str | None, int]:
        transfer = self.headers.get("Transfer-Encoding")
        if transfer is not None:
            return None, "Transfer-Encoding is not supported", HTTPStatus.BAD_REQUEST
        raw_length = self.headers.get("Content-Length")
        if raw_length is None:
            return None, "Content-Length is required", HTTPStatus.LENGTH_REQUIRED
        try:
            length = int(raw_length)
        except ValueError:
            return None, "invalid Content-Length", HTTPStatus.BAD_REQUEST
        if length < 0:
            return None, "invalid Content-Length", HTTPStatus.BAD_REQUEST
        if length > MAX_BODY:
            self.close_connection = True
            return None, "request body exceeds 1 MiB", HTTPStatus.REQUEST_ENTITY_TOO_LARGE
        data = self.rfile.read(length)
        if len(data) != length:
            return None, "incomplete request body", HTTPStatus.BAD_REQUEST
        try:
            return json.loads(
                data,
                parse_constant=lambda value: (_ for _ in ()).throw(
                    ValueError(f"invalid JSON constant: {value}")
                ),
            ), None, HTTPStatus.OK
        except (json.JSONDecodeError, UnicodeDecodeError):
            return None, "malformed JSON", HTTPStatus.BAD_REQUEST

    def do_GET(self) -> None:
        path = urlsplit(self.path).path
        try:
            if path == "/health":
                self._send(HTTPStatus.OK, {"status": "ok"})
            elif path == "/v1/keys":
                self._send(HTTPStatus.OK, {"keys": self.server.store.keys()})
            elif path.startswith("/v1/kv/"):
                key, error = self._key()
                if error:
                    self._error(HTTPStatus.BAD_REQUEST, error)
                    return
                found, value = self.server.store.get(key)
                if found:
                    self._send(HTTPStatus.OK, {"key": key, "value": value})
                else:
                    self._error(HTTPStatus.NOT_FOUND, "key not found")
            else:
                self._error(HTTPStatus.NOT_FOUND, "unknown route")
        except StoreError as exc:
            self.log_error("storage error: %s", exc)
            self._error(HTTPStatus.INTERNAL_SERVER_ERROR, "storage error")

    def do_PUT(self) -> None:
        key, error = self._key()
        if error:
            status = HTTPStatus.NOT_FOUND if error == "unknown route" else HTTPStatus.BAD_REQUEST
            self._error(status, error)
            return
        body, error, status = self._read_json()
        if error:
            self._error(status, error)
            return
        if not isinstance(body, dict) or "value" not in body or any(name not in {"value", "ttl_seconds"} for name in body):
            self._error(HTTPStatus.BAD_REQUEST, "body must be an object containing value and optional ttl_seconds")
            return
        ttl = body.get("ttl_seconds")
        if ttl is not None and (
            not isinstance(ttl, (int, float)) or isinstance(ttl, bool) or not math.isfinite(ttl) or ttl <= 0
        ):
            self._error(HTTPStatus.BAD_REQUEST, "ttl_seconds must be a finite number greater than zero")
            return
        try:
            created = self.server.store.put(key, body["value"], None if ttl is None else float(ttl))
            self._send(HTTPStatus.CREATED if created else HTTPStatus.OK, {"key": key, "value": body["value"]})
        except StoreError as exc:
            self.log_error("storage error: %s", exc)
            self._error(HTTPStatus.INTERNAL_SERVER_ERROR, "storage error")

    def do_DELETE(self) -> None:
        key, error = self._key()
        if error:
            status = HTTPStatus.NOT_FOUND if error == "unknown route" else HTTPStatus.BAD_REQUEST
            self._error(status, error)
            return
        try:
            if self.server.store.delete(key):
                self._send(HTTPStatus.NO_CONTENT)
            else:
                self._error(HTTPStatus.NOT_FOUND, "key not found")
        except StoreError as exc:
            self.log_error("storage error: %s", exc)
            self._error(HTTPStatus.INTERNAL_SERVER_ERROR, "storage error")

    def _unsupported(self) -> None:
        self._error(HTTPStatus.METHOD_NOT_ALLOWED, "method not allowed")

    do_POST = _unsupported
    do_PATCH = _unsupported
    do_OPTIONS = _unsupported
    do_HEAD = _unsupported


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description="Persistent HTTP key-value service")
    parser.add_argument("--host", default="127.0.0.1")
    parser.add_argument("--port", type=int, required=True)
    parser.add_argument("--data", type=Path, required=True)
    args = parser.parse_args()
    if not 0 <= args.port <= 65535:
        parser.error("--port must be between 0 and 65535")
    return args


def main() -> int:
    args = parse_args()
    try:
        store = PersistentStore(args.data)
        server = Server((args.host, args.port), store)
    except (OSError, StoreError) as exc:
        print(f"startup error: {exc}", file=sys.stderr)
        return 1

    stopping = threading.Event()

    def stop(_signum: int, _frame: Any) -> None:
        if not stopping.is_set():
            stopping.set()
            threading.Thread(target=server.shutdown, daemon=True).start()

    signal.signal(signal.SIGTERM, stop)
    signal.signal(signal.SIGINT, stop)
    print(f"LISTENING {server.server_address[1]}", flush=True)
    try:
        server.serve_forever(poll_interval=0.1)
    finally:
# Persistent HTTP key-value service

A dependency-free Python 3.11+ JSON API with TTL support and atomic on-disk persistence.

## Run

```sh
python3 server.py --host 127.0.0.1 --port 8080 --data ./data.json
```

Use `--port 0` to select a free port; the service prints `LISTENING <port>` as its first stdout line. Diagnostics go to stderr. Send `SIGTERM` or press Ctrl-C for a clean shutdown.

## API

```sh
curl -X PUT http://127.0.0.1:8080/v1/kv/my%20key \
  -H 'Content-Type: application/json' \
  -d '{"value":{"answer":42},"ttl_seconds":60}'
curl http://127.0.0.1:8080/v1/kv/my%20key
curl http://127.0.0.1:8080/v1/keys
curl -X DELETE http://127.0.0.1:8080/v1/kv/my%20key
curl http://127.0.0.1:8080/health
```

Values may be any JSON value. Keys are URL-encoded UTF-8, may contain spaces, and cannot be empty or contain `/`. Request bodies are limited to 1 MiB.

